INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('25e6436f2393661b6e80','Git amedex 2025.pdf','50','Gastroenterology','You prescribed triple therapy against Helicobacter pylori with clarithromycin, amoxicillin, and
esomeprazole for a 42-year-old patient of yours after his test results came back positive for the
infection and you considered it as the cause of his intractable dyspepsia. One week after
completing the treatment, he returns with reduced yet persisting symptoms. You arrange for a
breath urea test. The result of the test is positive indicating treatment failure. Which of the
following is the most likely cause of the failed treatment?','{"A":"OA. Resistance to clarithromycin.","B":"B. Resistance to amoxicillin.","C":"C. False positive breath urea test result.","D":"D. Poor adherence to the therapy.","E":"E. Misdiagnosis of the cause of dyspepsia."}','A','Triple therapy with clarithromycin, amoxicillin, and a proton pump inhibitor (PPI) for 7-14 days is
the regimen of choice for the treatment of H.pylori infection with over 90% response.
Clarithromycin is the most effective antibiotic against H.pylori.

The most common cause of treatment failure with this regimen is the increasing rates of
resistance of H.pylori to clarithromycin. This resistance cannot be overcome by dose increase or
lengthening the duration of therapy.

NOTE - In those with penicillin hypersensitivity, in whom amoxicillin cannot be used,
metronidazole can replace amoxicillin. So the regimen would be a combination of

metronidazole, clarithromycin, and a PPI. In such cases, resistance to either metronidazole
or clarithromycin, or even both, can be the cause of treatment failure.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[50],"source_qid":null,"duplicate_group_id":"exact-ad40f69d0db5","duplicate_sources":[{"record_id":"25e6436f2393661b6e80","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":50,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"25e6436f2393661b6e80","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":50,"supporting_pages":[50],"source_qid":null,"domain_hint":"Gastroenterology","stem":"You prescribed triple therapy against Helicobacter pylori with clarithromycin, amoxicillin, and\nesomeprazole for a 42-year-old patient of yours after his test results came back positive for the\ninfection and you considered it as the cause of his intractable dyspepsia. One week after\ncompleting the treatment, he returns with reduced yet persisting symptoms. You arrange for a\nbreath urea test. The result of the test is positive indicating treatment failure. Which of the\nfollowing is the most likely cause of the failed treatment?","options":{"A":"OA. Resistance to clarithromycin.","B":"B. Resistance to amoxicillin.","C":"C. False positive breath urea test result.","D":"D. Poor adherence to the therapy.","E":"E. Misdiagnosis of the cause of dyspepsia."},"source_answer":"A","source_explanation":"Triple therapy with clarithromycin, amoxicillin, and a proton pump inhibitor (PPI) for 7-14 days is\nthe regimen of choice for the treatment of H.pylori infection with over 90% response.\nClarithromycin is the most effective antibiotic against H.pylori.\n\nThe most common cause of treatment failure with this regimen is the increasing rates of\nresistance of H.pylori to clarithromycin. This resistance cannot be overcome by dose increase or\nlengthening the duration of therapy.\n\nNOTE - In those with penicillin hypersensitivity, in whom amoxicillin cannot be used,\nmetronidazole can replace amoxicillin. So the regimen would be a combination of\n\nmetronidazole, clarithromycin, and a PPI. In such cases, resistance to either metronidazole\nor clarithromycin, or even both, can be the cause of treatment failure.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["antibiotic","dose","duration","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ad40f69d0db57430ed05246aeb0b784fc756bbb6","duplicate_group_id":"exact-ad40f69d0db5","duplicate_sources":[{"record_id":"25e6436f2393661b6e80","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":50,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_ris