INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('da47e7777b7e9eb0fb5d','Git amedex 2025.pdf','53','Gastroenterology','Kim, 9 years old, is diagnosed with hepatitis A after she developed jaundice and abdominal pain 8 days ago.
Today, her mother calls and asks you when she can go back to school. Which one of the following would be your
answer?','{"A":"A. When her tests are normal.","B":"B. She can go back to school now if there is a separate sanitation system.","C":"OC. She can go to school now.","D":"D. After 4 to 6 months.","E":"E. After one month."}','C','The incubation period of hepatitis A is 15 to 50 days, but more commonly 28 to 30 days. The usual clinical
presentation is acute fever, malaise, anorexia, nausea, and abdominal discomfort (prodromal symptoms),
followed by dark urine and jaundice a few days later. Symptoms usually last several weeks.

The likelihood that symptoms will follow infection increases with age: jaundice occurs in only a small proportion of
infants and young children but in most adults. Infants and children infected with HAV may have mild or no
symptoms.

The viral load in the stool (and infectivity) is highest just before the onset of jaundice.

Patients are considered infectious from a few days before the onset of prodromal symptoms to a few days after
the onset of jaundice and non-infectious one week after the onset of jaundice (if it occurs) or two weeks (14 days)
after the onset of prodromal symptoms, whichever comes first.

Kim had jaundice eight days ago, and she does not seem to be infectious anymore because more than
seven days have passed since the jaundice. She can go back to school now.

Serum IgM anti-HAV is the gold standard for diagnosis. The antibody becomes positive at the onset of symptoms,
peaks during the acute or early convalescent phase, and remains positive for approximately 4 to 6 months. Liver
function tests may also remain deranged beyond the infection period. Liver function tests or HAV antibodies are
not appropriate indicators for infectivity.

NOTE - exclusion of contacts is not necessary.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[53],"source_qid":null,"duplicate_group_id":"exact-1b0a51c10d5f","duplicate_sources":[{"record_id":"da47e7777b7e9eb0fb5d","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":53,"source_qid":null},{"record_id":"f3bb02821a920ed1c0f5","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_page":41,"source_qid":null},{"record_id":"1c421b80299b06dbbeaa","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_page":42,"source_qid":null},{"record_id":"95c911c86c7ec9bec347","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":560,"source_qid":"1031"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"da47e7777b7e9eb0fb5d","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":53,"supporting_pages":[53],"source_qid":null,"domain_hint":"Gastroenterology","stem":"Kim, 9 years old, is diagnosed with hepatitis A after she developed jaundice and abdominal pain 8 days ago.\nToday, her mother calls and asks you when she can go back to school. Which one of the following would be your\nanswer?","options":{"A":"A. When her tests are normal.","B":"B. She can go back to school now if there is a separate sanitation system.","C":"OC. She can go to school now.","D":"D. After 4 to 6 months.","E":"E. After one month."},"source_answer":"C","source_explanation":"The incubation period of hepatitis A is 15 to 50 days, but more commonly 28 to 30 days. The usual clinical\npresentation is acute fever, malaise, anorexia, nausea, and abdominal discomfort (prodromal symptoms),\nfollowed by dark urine and jaundice a few days later. Symptoms usually last several weeks.\n\nThe likelihood that symptoms will follow infection increases with age: jaundice occurs in only a small proportion of\ninfants and young children but in most adults. Infants and children infected with HAV may have mild or no\nsymptoms.\n\nThe viral load in the stool (and infectivity) is highest just before the onset of jaundice.\n\nPatients are considered infectious from a few days before the onset of prodromal symptoms to a few days after\nthe onset of jaundice and non-infectious one week after the onset of jaundice (if it occurs) or two weeks (14 days)\nafter the onset of prodromal symptoms, whichever comes first.\n\nKim had jaundice eight days ago, and she does not seem to be infectious anymore because more than\nseven days have passed since the jaundice. She can go back to school now.\n\nSerum IgM anti-HAV is the gold standard for diagnosis. The antibody becomes positive at the onset of symptoms,\npeaks during the acute or early convalescent phase, and remains positive for approximately 4 to 6 months. Liver\nfunction tests may also remain deranged beyond the infection period. Liver function tests or HAV antibodies are\nnot appropriate indicators for infectivity.\n\nNOTE - exclusion of contacts is not necessary.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1b0a51c10d5f5c5cdcf03514a3dc4365083f6d89","duplicate_group_id":"exact-1b0a51c10d5f","duplicate_sources":[{"record_id":"da47e7777b7e9eb0fb5d","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":53,"source_qid":null},{"record_id":"f3bb02821a920ed1c0f5","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_page":41,"source_qid":null},{"record_id":"1c421b80299b06dbbeaa","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_page":42,"source_qid":null},{"record_id":"95c911c86c7ec9bec347","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":560,"source_qid":"1031"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
