INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8e1ac85048d548735fec','Git amedex 2025.pdf','56','Gastroenterology','A 42-year-old man is admitted with hematemesis. On examination, his blood pressure is 95/60 mmHg and his
pulse rate is 104 bpm. He has yellowish sclerae and bruises on his arms. Several spider nevi are noted on his
chest and abdomen. His abdomen is distended and soft, with evidence of shifting dullness. Dilated veins are
easily visible in the subcutaneous tissue, and the liver is palpable two fingers below the costal margin. Which
one of the following could be the most likely underlying cause of his problem?','{"A":"OA. Alcoholic liver disease.","B":"B. Biliary cirrhosis.","C":"C. Schistosomiasis.","D":"D. Budd-Chiari syndrome.","E":"E. Hepatitis C cirrhosis."}','A','Upper gastrointestinal bleeding may have different causes, but in this man, having the clinical features of liver
disease and cirrhosis, bleeding from esophageal varices would be the most likely cause of bleeding. Cirrhosis
results in portal vein hypertension.

When the portal vein is obstructed, shunting between the portal vein and systemic veins starts to develop. These
shunts lead to dilated veins around the umbilicus (caput medusa), in the lower gastrointestinal tract
(hemorrhoids), or the upper gastrointestinal tract (esophageal varices).

Other symptoms indicating chronic liver disease and cirrhosis in this patient are ascites, spider nevi, and bruises
on the arms that might have been caused by coagulopathy secondary to the liver disease.

In Australia, alcoholic liver disease is the most common cause of chronic liver disease and cirrhosis and the
most likely diagnosis from an epidemiological viewpoint. Hepatitis C infection (option E) is the second most
common cause of liver cirrhosis in Australia.

Biliary cirrhosis (option B), schistosomiasis (option C), and Budd-Chiari syndrome (option D) can all potentially
lead to liver cirrhosis and such a constellation of symptoms, but they are much less common than alcoholic liver
disease.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[56],"source_qid":null,"duplicate_group_id":"exact-838f496d9618","duplicate_sources":[{"record_id":"8e1ac85048d548735fec","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":56,"source_qid":null},{"record_id":"6646759fa1ae23446f5e","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":64,"source_qid":null},{"record_id":"dc7da88a052ecd0094c6","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":63,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8e1ac85048d548735fec","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":56,"supporting_pages":[56],"source_qid":null,"domain_hint":"Gastroenterology","stem":"A 42-year-old man is admitted with hematemesis. On examination, his blood pressure is 95/60 mmHg and his\npulse rate is 104 bpm. He has yellowish sclerae and bruises on his arms. Several spider nevi are noted on his\nchest and abdomen. His abdomen is distended and soft, with evidence of shifting dullness. Dilated veins are\neasily visible in the subcutaneous tissue, and the liver is palpable two fingers below the costal margin. Which\none of the following could be the most likely underlying cause of his problem?","options":{"A":"OA. Alcoholic liver disease.","B":"B. Biliary cirrhosis.","C":"C. Schistosomiasis.","D":"D. Budd-Chiari syndrome.","E":"E. Hepatitis C cirrhosis."},"source_answer":"A","source_explanation":"Upper gastrointestinal bleeding may have different causes, but in this man, having the clinical features of liver\ndisease and cirrhosis, bleeding from esophageal varices would be the most likely cause of bleeding. Cirrhosis\nresults in portal vein hypertension.\n\nWhen the portal vein is obstructed, shunting between the portal vein and systemic veins starts to develop. These\nshunts lead to dilated veins around the umbilicus (caput medusa), in the lower gastrointestinal tract\n(hemorrhoids), or the upper gastrointestinal tract (esophageal varices).\n\nOther symptoms indicating chronic liver disease and cirrhosis in this patient are ascites, spider nevi, and bruises\non the arms that might have been caused by coagulopathy secondary to the liver disease.\n\nIn Australia, alcoholic liver disease is the most common cause of chronic liver disease and cirrhosis and the\nmost likely diagnosis from an epidemiological viewpoint. Hepatitis C infection (option E) is the second most\ncommon cause of liver cirrhosis in Australia.\n\nBiliary cirrhosis (option B), schistosomiasis (option C), and Budd-Chiari syndrome (option D) can all potentially\nlead to liver cirrhosis and such a constellation of symptoms, but they are much less common than alcoholic liver\ndisease.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","hypertension"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"838f496d96187bd1c58aa550a5ed054776e40570","duplicate_group_id":"exact-838f496d9618","duplicate_sources":[{"record_id":"8e1ac85048d548735fec","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":56,"source_qid":null},{"record_id":"6646759fa1ae23446f5e","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":64,"source_qid":null},{"record_id":"dc7da88a052ecd0094c6","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":63,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
