INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c8d98d4bed050570ecea','Git amedex 2025.pdf','60','Gastroenterology','Which of the following is a contraindication to surgical intervention in esophageal malignancies?','{"A":"OA. Invasion to tracheobronchial tree.","B":"OB. Invasion to small blood vessels.","C":"C. Lesions greater than 5 cm.","D":"D. Odynophagia.","E":"E. Aspiration pneumonia."}','A','Surgery is the cornerstone of treatment for esophageal cancer; however, in the following situations
surgery is contraindicated:

Distant metastases — the presence of peritoneal, lung, bone, adrenal, brain, or liver metastasis, or
extraperitoneal lymph node spread (e.g., paraaortic or mesenteric lymphadenopathy). The approach to
patients with celiac lymph node involvement remains controversial.

Invasion to adjacent structures — the invasion of the tumor to the aorta, trachea, heart, great vessels, or
the presence of tracheoesophageal fistula (tumor stage: T4b)

NOTE — With invasion to the pleura, pericardium, or diaphragm the cancer is classified as T4a, and
considered potentially resectable.

In addition, severe, associated comorbid conditions such as cardiovascular or respiratory diseases
decrease a patient’s chance of survival and success of esophageal resection. Every patient should
undergo cardiac and respiratory function assessment prior to the surgery. A forced expiratory volume in
1 second (FEV1) less than 1.2 L and a left ventricular ejection fraction of less than 40% are relative
contraindications to the surgery.

Of the options, only invasion of the tumor to the tracheobronchial tree is a contraindication to surgical
resection.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[60],"source_qid":null,"duplicate_group_id":"exact-1ecef9210d65","duplicate_sources":[{"record_id":"c8d98d4bed050570ecea","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":60,"source_qid":null},{"record_id":"124098c991b93d331a13","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_page":124,"source_qid":null},{"record_id":"ba641c486363441339d7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":540,"source_qid":"697"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c8d98d4bed050570ecea","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":60,"supporting_pages":[60],"source_qid":null,"domain_hint":"Gastroenterology","stem":"Which of the following is a contraindication to surgical intervention in esophageal malignancies?","options":{"A":"OA. Invasion to tracheobronchial tree.","B":"OB. Invasion to small blood vessels.","C":"C. Lesions greater than 5 cm.","D":"D. Odynophagia.","E":"E. Aspiration pneumonia."},"source_answer":"A","source_explanation":"Surgery is the cornerstone of treatment for esophageal cancer; however, in the following situations\nsurgery is contraindicated:\n\nDistant metastases — the presence of peritoneal, lung, bone, adrenal, brain, or liver metastasis, or\nextraperitoneal lymph node spread (e.g., paraaortic or mesenteric lymphadenopathy). The approach to\npatients with celiac lymph node involvement remains controversial.\n\nInvasion to adjacent structures — the invasion of the tumor to the aorta, trachea, heart, great vessels, or\nthe presence of tracheoesophageal fistula (tumor stage: T4b)\n\nNOTE — With invasion to the pleura, pericardium, or diaphragm the cancer is classified as T4a, and\nconsidered potentially resectable.\n\nIn addition, severe, associated comorbid conditions such as cardiovascular or respiratory diseases\ndecrease a patient’s chance of survival and success of esophageal resection. Every patient should\nundergo cardiac and respiratory function assessment prior to the surgery. A forced expiratory volume in\n1 second (FEV1) less than 1.2 L and a left ventricular ejection fraction of less than 40% are relative\ncontraindications to the surgery.\n\nOf the options, only invasion of the tumor to the tracheobronchial tree is a contraindication to surgical\nresection.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1ecef9210d65d8183ffa819d185ee181d48e6bb1","duplicate_group_id":"exact-1ecef9210d65","duplicate_sources":[{"record_id":"c8d98d4bed050570ecea","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":60,"source_qid":null},{"record_id":"124098c991b93d331a13","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_page":124,"source_qid":null},{"record_id":"ba641c486363441339d7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":540,"source_qid":"697"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
