INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3ea61d24df1f20187784','Git amedex 2025.pdf','61','Gastroenterology','Which one of the following is the most useful investigation for detection of gallstones and
dilatation of the common bile duct?','{"A":"A. Hepatobiliary iminodiacetic acid (HIDA) scintigraphy.","B":"OB. Ultrasound.","C":"C. Endoscopic retrograde cholangiopancreatography (ERCP).","D":"D. X-ray.","E":"E. Liver isotope scan."}','B','Ultrasound is the most useful investigation for detecting gallstones and dilatation of the
common bile duct. It is also helpful in detecting hepatic metastases and some liver
diseases.

(Option A) HIDA scan is used if sonographic studies are equivocal. On the scan, the liver,
CBD, and duodenum light up; the gallbladder will not if inflamed.

(Option C) ERCP is used for visual detection and retrieval of stones in the CBD and other
causes of obstructive jaundice.

(Option D) Since only 10% of gallstones are radio-opaque, abdominal X-ray will be able to
pick up gallstones in only up to 10% of cases; hence, not a preferred method.

(Option E) The liver isotopic scan is helpful for the evaluation of hepatic cirrhosis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[61],"source_qid":null,"duplicate_group_id":"exact-0619cfa4ec9d","duplicate_sources":[{"record_id":"3ea61d24df1f20187784","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":61,"source_qid":null},{"record_id":"19fef658cbcb78cfc825","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":49,"source_qid":null},{"record_id":"1938c4e16fee138d3aa5","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":50,"source_qid":null},{"record_id":"861acd0086181eb3bf58","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":501,"source_qid":"478"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"3ea61d24df1f20187784","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":61,"supporting_pages":[61],"source_qid":null,"domain_hint":"Gastroenterology","stem":"Which one of the following is the most useful investigation for detection of gallstones and\ndilatation of the common bile duct?","options":{"A":"A. Hepatobiliary iminodiacetic acid (HIDA) scintigraphy.","B":"OB. Ultrasound.","C":"C. Endoscopic retrograde cholangiopancreatography (ERCP).","D":"D. X-ray.","E":"E. Liver isotope scan."},"source_answer":"B","source_explanation":"Ultrasound is the most useful investigation for detecting gallstones and dilatation of the\ncommon bile duct. It is also helpful in detecting hepatic metastases and some liver\ndiseases.\n\n(Option A) HIDA scan is used if sonographic studies are equivocal. On the scan, the liver,\nCBD, and duodenum light up; the gallbladder will not if inflamed.\n\n(Option C) ERCP is used for visual detection and retrieval of stones in the CBD and other\ncauses of obstructive jaundice.\n\n(Option D) Since only 10% of gallstones are radio-opaque, abdominal X-ray will be able to\npick up gallstones in only up to 10% of cases; hence, not a preferred method.\n\n(Option E) The liver isotopic scan is helpful for the evaluation of hepatic cirrhosis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0619cfa4ec9d83f50978b18084ff781ef9b8ac12","duplicate_group_id":"exact-0619cfa4ec9d","duplicate_sources":[{"record_id":"3ea61d24df1f20187784","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":61,"source_qid":null},{"record_id":"19fef658cbcb78cfc825","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":49,"source_qid":null},{"record_id":"1938c4e16fee138d3aa5","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":50,"source_qid":null},{"record_id":"861acd0086181eb3bf58","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":501,"source_qid":"478"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
