INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('3ea61d24df1f20187784','src-v294-15e0902a',NULL,'61','Gastroenterology','Gastroenterology','Gastroenterology','AMC MCQ','Which one of the following is the most useful investigation for detection of gallstones and
dilatation of the common bile duct?',NULL,'B','Ultrasound is the most useful investigation for detecting gallstones and dilatation of the
common bile duct. It is also helpful in detecting hepatic metastases and some liver
diseases.

(Option A) HIDA scan is used if sonographic studies are equivocal. On the scan, the liver,
CBD, and duodenum light up; the gallbladder will not if inflamed.

(Option C) ERCP is used for visual detection and retrieval of stones in the CBD and other
causes of obstructive jaundice.

(Option D) Since only 10% of gallstones are radio-opaque, abdominal X-ray will be able to
pick up gallstones in only up to 10% of cases; hence, not a preferred method.

(Option E) The liver isotopic scan is helpful for the evaluation of hepatic cirrhosis.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[61],"source_qid":null,"duplicate_group_id":"exact-0619cfa4ec9d","duplicate_sources":[{"record_id":"3ea61d24df1f20187784","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":61,"source_qid":null},{"record_id":"19fef658cbcb78cfc825","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":49,"source_qid":null},{"record_id":"1938c4e16fee138d3aa5","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":50,"source_qid":null},{"record_id":"861acd0086181eb3bf58","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":501,"source_qid":"478"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','low') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options