INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ba4b1509fb29f2ded3ad','Git amedex 2025.pdf','64','Gastroenterology','A 57-year-old man presents to the emergency department with fever and right upper quadrant
pain. Upon examination, he had a blood pressure of 80/60mmHg, pulse rate of 110 bpm,
respiratory rate of 22 breaths per minute, and temperature of 38.9°C. The right upper quadrant
is tender to palpation. Laboratory studies reveal high white cell count and mildly elevated
bilirubin. Based on the findings, you suspect acute cholangitis as the diagnosis. Which one of
the following organisms is most likely to have caused sepsis?','{"A":"A. Staphylococcus aureus.","B":"B. Pseudomonas aeruginosa.","C":"C. Enterococcus fecalis.","D":"OD. Escherichia coli.","E":"E. Treponema pallidum."}','D','Acute cholangitis is a clinical syndrome characterized by fever, abdominal pain, and jaundice,
developing due to stasis and infection in the biliary tract. It can rapidly progress to sepsis. Biliary
system obstruction is the most common predisposing factor.

Culture of bile, ductal stones, and blocked biliary stents are positive in over 90% of cases,
yielding a mixed growth of gram-negative and gram-positive bacteria. The most common
bacteria isolated have a colonic origin.

Escherichia coli is the primary bacterium isolated (25 to 50%), followed by Klebsiella (15-20%)
and Enterobacter species (5-10%). Enterococcus species (e.g., enterococcus fecalis) are the
most common gram-positive bacteria (10-20%).

Anaerobes, such as Bacteroides and Clostridia, are usually present as isolated pathogens, but
they are rarely the sole infecting organisms, and it is unclear if they play a role in acute
cholangitis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[64],"source_qid":null,"duplicate_group_id":"exact-6cf6d51ef140","duplicate_sources":[{"record_id":"ba4b1509fb29f2ded3ad","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":64,"source_qid":null},{"record_id":"c1e5925fa6024b4e6f22","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_page":54,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"ba4b1509fb29f2ded3ad","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":64,"supporting_pages":[64],"source_qid":null,"domain_hint":"Gastroenterology","stem":"A 57-year-old man presents to the emergency department with fever and right upper quadrant\npain. Upon examination, he had a blood pressure of 80/60mmHg, pulse rate of 110 bpm,\nrespiratory rate of 22 breaths per minute, and temperature of 38.9°C. The right upper quadrant\nis tender to palpation. Laboratory studies reveal high white cell count and mildly elevated\nbilirubin. Based on the findings, you suspect acute cholangitis as the diagnosis. Which one of\nthe following organisms is most likely to have caused sepsis?","options":{"A":"A. Staphylococcus aureus.","B":"B. Pseudomonas aeruginosa.","C":"C. Enterococcus fecalis.","D":"OD. Escherichia coli.","E":"E. Treponema pallidum."},"source_answer":"D","source_explanation":"Acute cholangitis is a clinical syndrome characterized by fever, abdominal pain, and jaundice,\ndeveloping due to stasis and infection in the biliary tract. It can rapidly progress to sepsis. Biliary\nsystem obstruction is the most common predisposing factor.\n\nCulture of bile, ductal stones, and blocked biliary stents are positive in over 90% of cases,\nyielding a mixed growth of gram-negative and gram-positive bacteria. The most common\nbacteria isolated have a colonic origin.\n\nEscherichia coli is the primary bacterium isolated (25 to 50%), followed by Klebsiella (15-20%)\nand Enterobacter species (5-10%). Enterococcus species (e.g., enterococcus fecalis) are the\nmost common gram-positive bacteria (10-20%).\n\nAnaerobes, such as Bacteroides and Clostridia, are usually present as isolated pathogens, but\nthey are rarely the sole infecting organisms, and it is unclear if they play a role in acute\ncholangitis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6cf6d51ef140ede1a477568aec0fee1609a09e6d","duplicate_group_id":"exact-6cf6d51ef140","duplicate_sources":[{"record_id":"ba4b1509fb29f2ded3ad","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":64,"source_qid":null},{"record_id":"c1e5925fa6024b4e6f22","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_page":54,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_expl