INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('78b2400931a21f962207','Git amedex 2025.pdf','75','Gastroenterology','A 42-year-old man presents with a 10-month history of nocturnal gastric acid reflux. He smokes 40 cigarettes a
day, drinks alcohol regularly, and drinks 4 cups of coffee daily. He loves spicy foods and eats a lot of them. On
examination, his height is 178 cm, and weighs 110 kg. He has a waist circumference of 115 cm. Which one of
the following is the most appropriate advice for him regarding the long-term management of the condition?','{"A":"A. He should stop drinking alcohol.","B":"B. He should stop smoking.","C":"C. He should avoid spicy foods.","D":"OD. He should reduce weight.","E":"E. He should stop drinking coffee."}','D','In conjunction with antacid therapy, advice regarding lifestyle modification has historically been part of the
management plan for gastroesophageal reflux disease (GERD). Mild cases will respond to simple measures
(e.g., bed head elevation), while most will need proton pump inhibitors (PPIs) as the cornerstone of the
treatment.

Lifestyle modifications that are often advised include:

¢ Weight reduction

¢ Bedhead elevation during sleep

¢ Avoiding spicy foods

¢ Last meal no later than 2-3 hours before bedtime
¢ Avoiding or reducing alcohol and caffeine intake
* Quitting smoking

Of these, however, only elevation of the head of the bed and weight reduction seems to have an effect more
than a placebo. While widely encouraged, other measures appear to be associated with improved overall health
with no specific effect on GERD, at least not in all patients.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[75],"source_qid":null,"duplicate_group_id":"exact-1fc48b3c0d4d","duplicate_sources":[{"record_id":"78b2400931a21f962207","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":75,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"78b2400931a21f962207","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":75,"supporting_pages":[75],"source_qid":null,"domain_hint":"Gastroenterology","stem":"A 42-year-old man presents with a 10-month history of nocturnal gastric acid reflux. He smokes 40 cigarettes a\nday, drinks alcohol regularly, and drinks 4 cups of coffee daily. He loves spicy foods and eats a lot of them. On\nexamination, his height is 178 cm, and weighs 110 kg. He has a waist circumference of 115 cm. Which one of\nthe following is the most appropriate advice for him regarding the long-term management of the condition?","options":{"A":"A. He should stop drinking alcohol.","B":"B. He should stop smoking.","C":"C. He should avoid spicy foods.","D":"OD. He should reduce weight.","E":"E. He should stop drinking coffee."},"source_answer":"D","source_explanation":"In conjunction with antacid therapy, advice regarding lifestyle modification has historically been part of the\nmanagement plan for gastroesophageal reflux disease (GERD). Mild cases will respond to simple measures\n(e.g., bed head elevation), while most will need proton pump inhibitors (PPIs) as the cornerstone of the\ntreatment.\n\nLifestyle modifications that are often advised include:\n\n¢ Weight reduction\n\n¢ Bedhead elevation during sleep\n\n¢ Avoiding spicy foods\n\n¢ Last meal no later than 2-3 hours before bedtime\n¢ Avoiding or reducing alcohol and caffeine intake\n* Quitting smoking\n\nOf these, however, only elevation of the head of the bed and weight reduction seems to have an effect more\nthan a placebo. While widely encouraged, other measures appear to be associated with improved overall health\nwith no specific effect on GERD, at least not in all patients.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1fc48b3c0d4daf4634ac6049d7ba60d8ba6cba8b","duplicate_group_id":"exact-1fc48b3c0d4d","duplicate_sources":[{"record_id":"78b2400931a21f962207","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":75,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=exc