ts with toxic megacolon typically appear very ill with fever, tachycardia, and abdominal tenderness. There is often a\nhistory of bloody diarrhea or other signs and symptoms of chronic inflammatory bowel disease.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","duration"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a93e4b190d010b52b9c84979a05e6b8ac525c710","duplicate_group_id":"exact-a93e4b190d01","duplicate_sources":[{"record_id":"9921e0f348f809fce1b1","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":77,"source_qid":null},{"record_id":"ccba25eb4559515224aa","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_page":105,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
